l_int32 generateImageHTMLViewer(const char* dirin, const char* dirout, const char* rootname, l_int32 thumbwidth, l_int32 viewwidth) {
    char **filelist = NULL;
    l_int32 count, i, ret;

    if (!dirin || !dirout || !rootname || thumbwidth <= 0 || viewwidth <= 0) {
        return -1; // Invalid input
    }

    // Create output directory if it doesn't exist
    if ((ret = lept_mkdir(dirout)) != 0) {
        return ret;
    }

    // Retrieve image filenames from the input directory
    if ((ret = getFilenamesInDirectory(dirin, &filelist)) != 0) {
        return ret;
    }

    if ((count = (l_int32)filelist[0]) <= 0) {
        return -2; // No files found
    }

    // Generate thumbnails
    for (i = 1; i <= count; i++) {
        char *srcPath = filelist[i];
        char *destPath = filelist[i];
        if ((ret = generateThumbnail(srcPath, dirout, thumbwidth)) != 0) {
            return ret;
        }
    }

    // Generate viewable images
    for (i = 1; i <= count; i++) {
        char *srcPath = filelist[i];
        char *destPath = filelist[i];
        if ((ret = generateViewableImage(srcPath, dirout, viewwidth)) != 0) {
            return ret;
        }
    }

    // Write main HTML viewer
    if ((ret = writeHTMLViewer(rootname, dirout, dirin, filelist, count)) != 0) {
        return ret;
    }

    // Write HTML links file
    if ((ret = writeHTMLLinks(rootname, dirout, dirin, filelist, count)) != 0) {
        return ret;
    }

    return 0; // Success
}

l_int32 generate_html_viewer(const char* dirin, const char* dirout, const char* rootname, l_int32 thumbwidth, l_int32 viewwidth) {
    if (!dirin || !dirout || !rootname) {
        fprintf(stderr, "Invalid input parameters.\n");
        return 1;
    }

    if (!fileExists(dirin)) {
        fprintf(stderr, "Input directory does not exist.\n");
        return 2;
    }

    if (!directoryExists(dirout)) {
        if (mkdir(dirout, 0777) != 0) {
            perror("Failed to create output directory");
            return 3;
        }
    }

    // Get list of image files in dirin
    char** imageFiles = NULL;
    l_int32 count = 0;
    l_int32 result = getSortedFileList(dirin, &imageFiles, &count);
    if (result != 0) {
        fprintf(stderr, "Failed to get image file list.\n");
        return 4;
    }

    if (count == 0) {
        fprintf(stderr, "No image files found in the input directory.\n");
        FREE_FILE_LIST(imageFiles, count);
        return 5;
    }

    // Generate HTML content
    char mainHtmlPath[1024];
    char linkHtmlPath[1024];
    snprintf(mainHtmlPath, sizeof(mainHtmlPath), "%s/%s.html", dirout, rootname);
    snprintf(linkHtmlPath, sizeof(linkHtmlPath), "%s/%s_links.html", dirout, rootname);

    FILE* mainHtmlFile = fopen(mainHtmlPath, "w");
    FILE* linkHtmlFile = fopen(linkHtmlPath, "w");

    if (!mainHtmlFile || !linkHtmlFile) {
        fprintf(stderr, "Failed to create HTML files.\n");
        FREE_FILE_LIST(imageFiles, count);
        return 6;
    }

    // Write HTML headers
    fprintf(mainHtmlFile, "<html><head><title>Image Viewer</title></head><body>\n");
    fprintf(linkHtmlFile, "<html><head><title>Image Links</title></head><body>\n");

    for (l_int32 i = 0; i < count; ++i) {
        char* filename = imageFiles[i];
        char baseName[1024];
        char* ext = strrchr(filename, '.');
        if (ext && (!strcmp(ext, ".png") || !strcmp(ext, ".jpg") || !strcmp(ext, ".jpeg") || !strcmp(ext, ".gif"))) {
            strncpy(baseName, filename, sizeof(baseName));
            baseName[sizeof(baseName) - 1] = '\0';
            char* dot = strrchr(baseName, '.');
            if (dot) {
                *dot = '\0';
            }

            char thumbnailPath[1024];
            char viewImagePath[1024];
            snprintf(thumbnailPath, sizeof(thumbnailPath), "%s/%s_thumb.jpg", dirout, baseName);
            snprintf(viewImagePath, sizeof(viewImagePath), "%s/%s_view.jpg", dirout, baseName);

            // Generate thumbnail and view image (placeholder for actual image processing)
            if (!generateThumbnail(dirin, filename, thumbnailPath, thumbwidth)) {
                fprintf(stderr, "Failed to generate thumbnail for %s.\n", filename);
            }

            if (!generateViewImage(dirin, filename, viewImagePath, viewwidth)) {
                fprintf(stderr, "Failed to generate view image for %s.\n", filename);
            }

            // Write HTML content
            fprintf(mainHtmlFile, "<a href=\"#\" onclick=\"openImage('%s')\"><img src=\"%s\" alt=\"Thumbnail %d\"></a>\n", viewImagePath, thumbnailPath, i + 1);
            fprintf(linkHtmlFile, "<p><a href=\"%s\">%s</a></p>\n", viewImagePath, filename);
        }
    }

    // Write HTML footers
    fprintf(mainHtmlFile, "<script>\nfunction openImage(src) {\n    window.open(src, '_blank');\n}\n</script>\n</body></html>\n");
    fprintf(linkHtmlFile, "</body></html>\n");

    fclose(mainHtmlFile);
    fclose(linkHtmlFile);

    FREE_FILE_LIST(imageFiles, count);
    return 0;
}

