l_int32 generate_html_image_viewer(const char* dirin, const char* dirout, const char* rootname, l_int32 thumbwidth, l_int32 viewwidth) {
    if (!dirin || !dirout || !rootname || thumbwidth <= 0 || viewwidth <= 0) {
        return 1; // Invalid input
    }

    if (makePath(dirout) < 0) {
        return 2; // Failed to create output directory
    }

    SARRAY* filenames = getFilenames(dirin);
    if (!filenames) {
        return 3; // No files or error retrieving filenames
    }

    l_int32 count = sarrayGetCount(filenames);
    for (l_int32 i = 0; i < count; ++i) {
        const char* src_file = sarrayGetString(filenames, i, L_NOCOPY);
        char* full_src_path = genPathname(dirin, src_file);

        Pix* image = pixRead(full_src_path);
        FREE(full_src_path);
        if (!image) {
            continue; // Skip if unable to read the image
        }

        Pix* thumb = pixScaleToWidth(image, thumbwidth);
        if (!thumb) {
            pixDestroy(&image);
            continue;
        }

        Pix* view = pixScaleToWidth(image, viewwidth);
        if (!view) {
            pixDestroy(&thumb);
            pixDestroy(&image);
            continue;
        }

        char* thumb_file = genPathname(dirout, src_file);
        char* view_file = genPathname(dirout, src_file);
        char* thumb_file_root = replaceSubstr(thumb_file, ".png", "_thumb.png"); // Adjust based on actual format
        char* view_file_root = replaceSubstr(view_file, ".png", "_view.png");

        FREE(thumb_file);
        FREE(view_file);

        pixWrite(thumb_file_root, thumb, IFF_PNG);
        pixWrite(view_file_root, view, IFF_PNG);

        FREE(thumb_file_root);
        FREE(view_file_root);

        pixDestroy(&thumb);
        pixDestroy(&view);
        pixDestroy(&image);
    }

    char* main_html_path = genPathname(dirout, rootname);
    char* links_html_path = genPathname(dirout, "links.html");

    // Write main HTML with thumbnail and viewable image links
    FILE* main_html = fopen(main_html_path, "w");
    if (!main_html) {
        FREE(main_html_path);
        FREE(links_html_path);
        sarrayDestroy(&filenames);
        return 4;
    }

    fprintf(main_html, "<html><body>\n");
    for (l_int32 i = 0; i < count; ++i) {
        const char* src_file = sarrayGetString(filenames, i, L_NOCOPY);
        char* thumb_file_root = genPathname(dirout, src_file);
        char* view_file_root = genPathname(dirout, src_file);
        char* thumb_name = replaceSubstr(thumb_file_root, ".png", "_thumb.png");
        char* view_name = replaceSubstr(view_file_root, ".png", "_view.png");

        fprintf(main_html, "<a href=\"%s\"><img src=\"%s\" alt=\"%s\"></a>\n", view_name, thumb_name, src_file);

        FREE(thumb_file_root);
        FREE(view_file_root);
        FREE(thumb_name);
        FREE(view_name);
    }
    fprintf(main_html, "</body></html>");
    fclose(main_html);
    FREE(main_html_path);

    // Write links HTML for individual image pages
    FILE* links_html = fopen(links_html_path, "w");
    if (!links_html) {
        FREE(links_html_path);
        sarrayDestroy(&filenames);
        return 4;
    }

    for (l_int32 i = 0; i < count; ++i) {
        const char* src_file = sarrayGetString(filenames, i, L_NOCOPY);
        char* view_name = genPathname(dirout, src_file);
        view_name = replaceSubstr(view_name, ".png", "_view.png");

        fprintf(links_html, "<html><body><h1>%s</h1><img src=\"%s\"></body></html>\n", src_file, view_name);
        FREE(view_name);
    }

    fclose(links_html);
    FREE(links_html_path);
    sarrayDestroy(&filenames);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
