#include "leptonlib.h"  // Assuming l_int32 and related functions are defined here

l_int32 generateHtmlImageViewer(const char *dirin, const char *dirout, const char *rootname, l_int32 thumbwidth, l_int32 viewwidth) {
    if (!dirin || !dirout || !rootname) {
        fprintf(stderr, "Invalid input parameters.\n");
        return 1;
    }

    // Ensure dirout exists
    struct stat st;
    if (stat(dirout, &st) == -1) {
        if (mkdir(dirout, 0777) == -1) {
            perror("Error creating output directory");
            return 2;
        }
    }

    // Open input directory
    DIR *dp = opendir(dirin);
    if (!dp) {
        perror("Error opening input directory");
        return 3;
    }

    struct dirent *entry;
    char htmlMainPath[1024];
    char htmlLinksPath[1024];
    snprintf(htmlMainPath, sizeof(htmlMainPath), "%s/%s.html", dirout, rootname);
    snprintf(htmlLinksPath, sizeof(htmlLinksPath), "%s/%s_links.html", dirout, rootname);

    FILE *mainHtml = fopen(htmlMainPath, "w");
    if (!mainHtml) {
        perror("Error creating main HTML file");
        closedir(dp);
        return 4;
    }

    FILE *linksHtml = fopen(htmlLinksPath, "w");
    if (!linksHtml) {
        perror("Error creating links HTML file");
        fclose(mainHtml);
        closedir(dp);
        return 5;
    }

    // Write HTML headers
    fprintf(mainHtml, "<!DOCTYPE html>\n<html>\n<head>\n<title>Image Viewer</title>\n</head>\n<body>\n");
    fprintf(linksHtml, "<!DOCTYPE html>\n<html>\n<head>\n<title>Image Links</title>\n</head>\n<body>\n");

    while ((entry = readdir(dp)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;

        char imagePath[1024];
        snprintf(imagePath, sizeof(imagePath), "%s/%s", dirin, entry->d_name);

        char thumbPath[1024];
        char viewPath[1024];
        char baseName[1024];
        char ext[1024];

        // Extract base name and extension
        char *dot = strrchr(entry->d_name, '.');
        if (dot) {
            strncpy(baseName, entry->d_name, dot - entry->d_name);
            baseName[dot - entry->d_name] = '\0';
            strcpy(ext, dot);
        } else {
            strcpy(baseName, entry->d_name);
            strcpy(ext, "");
        }

        snprintf(thumbPath, sizeof(thumbPath), "%s/%s_thumb%s", dirout, baseName, ext);
        snprintf(viewPath, sizeof(viewPath), "%s/%s_view%s", dirout, baseName, ext);

        // Generate thumbnail and view image (implementation omitted for brevity)
        // Use appropriate image processing functions (from leptonlib or similar)

        // Write to HTML
        fprintf(mainHtml, "<img src=\"%s\" width=\"%d\">", thumbPath, thumbwidth);
        fprintf(mainHtml, "<a href=\"%s\">%s</a><br>\n", viewPath, entry->d_name);
        fprintf(linksHtml, "<a href=\"%s\">%s</a><br>\n", viewPath, entry->d_name);
    }

    // Write HTML footers
    fprintf(mainHtml, "</body>\n</html>\n");
    fprintf(linksHtml, "</body>\n</html>\n");

    // Clean up
    fclose(mainHtml);
    fclose(linksHtml);
    closedir(dp);

    return 0;
}
